insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_83_v1'
from (values
('127.677.d.1.A',3,'Which event would most clearly create a need for digital forensics?','["a company discovers an employee copied confidential files to a personal drive", "a desk is moved", "a monitor is replaced", "a keyboard is cleaned"]'::jsonb,0,'Suspected data theft calls for an investigation.','original'),
('127.677.d.1.A',4,'Digital forensics helps an organization determine:','["how to schedule lunch breaks", "what happened, how it happened, and who was involved", "which paint color to buy", "what font to use in reports"]'::jsonb,1,'Forensics answers questions about incidents.','original'),
('127.677.d.1.B',3,'Which credential is aimed at digital forensics professionals?','["Food Safety Manager", "Certified Public Accountant", "GIAC Certified Forensic Examiner (GCFE)", "Commercial Pilot License"]'::jsonb,2,'GCFE validates forensic examination skills.','original'),
('127.677.d.1.B',4,'Earning a forensics certification helps a job seeker mainly by:','["replacing all experience", "guaranteeing a promotion", "avoiding background checks", "showing validated knowledge of investigation methods and tools"]'::jsonb,3,'Certifications signal verified skills.','original'),
('127.677.d.1.C',3,'Which government agency investigates federal cybercrimes and uses digital forensics?','["the Federal Bureau of Investigation (FBI)", "a school cafeteria board", "a local garden club", "a city parks mural committee"]'::jsonb,0,'The FBI investigates federal cybercrime.','original'),
('127.677.d.1.C',4,'Which business is most likely to employ in-house digital forensics investigators?','["a roadside fruit stand", "a bank investigating fraud and data theft", "a bakery with no computers", "a car wash"]'::jsonb,1,'Financial firms face fraud and breaches.','original'),
('127.677.d.1.D',3,'Digital forensics specialists commonly investigate crimes such as:','["littering", "jaywalking", "fraud, identity theft and unauthorized network access", "parking tickets"]'::jsonb,2,'These crimes leave digital evidence.','original'),
('127.677.d.1.D',4,'Which crime would most likely require recovering deleted emails and file histories as evidence?','["a noisy neighbor", "a lost library book", "a missed bus", "embezzlement carried out through accounting software"]'::jsonb,3,'Financial crimes leave digital trails.','original'),
('127.677.d.2.A',3,'An effective plan to promote ethical online behavior in a school would include:','["clear expectations, training and consequences for violations", "secret rules", "no communication", "rewarding rule breaking"]'::jsonb,0,'Plans need expectations, education and accountability.','original'),
('127.677.d.2.A',4,'Which activity best advocates for legal behavior online among peers?','["hiding scam links", "teaching classmates why copyright and privacy laws matter", "ignoring posts that break rules", "sharing pirated files"]'::jsonb,1,'Education promotes lawful conduct.','original'),
('127.677.d.2.B',3,'Laws that govern when someone may access stored electronic communications are part of:','["maritime law", "traffic law", "privacy and electronic communications law", "zoning law"]'::jsonb,2,'These laws protect electronic communications.','original'),
('127.677.d.2.B',4,'The Stored Communications Act, part of ECPA, mainly limits:','["building heights", "driving speeds", "food labels", "unauthorized access to stored electronic communications"]'::jsonb,3,'It restricts access to stored messages.','original'),
('127.677.d.2.C',3,'Studying a historic digital forensics case helps students learn:','["how investigators gathered and used evidence", "how to delete logs", "how to avoid all laws", "which crimes are harmless"]'::jsonb,0,'Cases show real investigative methods.','original'),
('127.677.d.2.C',4,'Forensic investigations of major retail breaches showed that attacks can be traced back to:','["the store''s paint color", "their entry point, such as a compromised vendor account", "the parking lot lights", "the CEO''s lunch order"]'::jsonb,1,'Tracing identifies how attackers got in.','original'),
('127.677.d.2.D',3,'While examining a seized laptop, an investigator sees unrelated private family photos. The ethical action is to:','["keep copies", "show coworkers", "avoid sharing them and limit review to what the case requires", "post them online"]'::jsonb,2,'Investigators respect unrelated private data.','original'),
('127.677.d.2.D',4,'An investigator who finds privileged attorney-client emails on a device should:','["delete the device", "send them to the press", "read them all", "stop and follow legal procedures for handling privileged material"]'::jsonb,3,'Privileged material needs special handling.','original'),
('127.677.d.2.E',3,'When analyzing a computer incident case study, the first goal is usually to establish:','["a timeline of what occurred", "the cheapest hardware", "the best desktop theme", "a new logo"]'::jsonb,0,'Timelines organize events.','original'),
('127.677.d.2.E',4,'Comparing several incident case studies helps investigators:','["ignore evidence", "recognize common attack patterns and mistakes", "skip documentation", "avoid all future incidents guaranteed"]'::jsonb,1,'Patterns repeat across incidents.','original'),
('127.677.d.2.F',3,'Reconstructing an incident means:','["guessing without evidence", "erasing the logs", "using evidence to rebuild the sequence of events", "blaming the newest employee"]'::jsonb,2,'Reconstruction is evidence-based.','original'),
('127.677.d.2.F',4,'Which evidence combination best helps reconstruct who accessed a file and when?','["keyboard brands", "screen savers and wallpapers", "mouse pads", "access logs and file timestamps"]'::jsonb,3,'Logs and timestamps show who and when.','original'),
('127.677.d.2.G',3,'A legal right that protects original creative works such as software code is:','["copyright", "zoning", "tariff", "probation"]'::jsonb,0,'Copyright covers original works.','original'),
('127.677.d.2.G',4,'A secret formula or algorithm a company keeps confidential is protected as a:','["free sample", "trade secret", "open license", "public record"]'::jsonb,1,'Trade secrets are protected by secrecy.','original'),
('127.677.d.2.H',3,'Which method of gathering information is legal?','["installing spyware on a stranger''s phone", "breaking into a server", "reading publicly posted company announcements", "guessing someone''s password"]'::jsonb,2,'Public information is lawful to read.','original'),
('127.677.d.2.H',4,'An investigator needs a search warrant or consent before:','["viewing a press release", "reading a public website", "visiting a public library", "examining a person''s private device"]'::jsonb,3,'Private devices are legally protected.','original'),
('127.677.d.2.I',3,'Which action is an ethical way to gather information for a case?','["collecting only what is needed and documenting how it was obtained", "tricking people into sharing passwords", "collecting everything possible secretly", "falsifying notes"]'::jsonb,0,'Ethical gathering is limited and documented.','original'),
('127.677.d.2.I',4,'Deceiving a witness by posing as someone else to obtain their data is generally considered:','["a best practice", "unethical and possibly illegal", "a required procedure", "always allowed"]'::jsonb,1,'Deception to get data violates ethics and law.','original'),
('127.677.d.2.J',3,'Growing public concern about data privacy has led to new:','["taxes on keyboards", "laws banning all computers", "laws that limit how personal data is collected", "rules requiring open passwords"]'::jsonb,2,'Privacy laws have expanded.','original'),
('127.677.d.2.J',4,'Which trend creates new legal questions for forensics investigators?','["paper filing", "handwritten letters only", "typewriter repair", "evidence stored in cloud services across countries"]'::jsonb,3,'Cross-border cloud data complicates jurisdiction.','original'),
('127.677.d.2.K',3,'Laws often lag behind technology because:','["technology changes faster than legislation can be written", "courts forbid updates", "lawmakers avoid computers by rule", "technology never changes"]'::jsonb,0,'Lawmaking is slower than innovation.','original'),
('127.677.d.2.K',4,'When new technology emerges, courts and legislators often:','["delete old laws instantly", "update or reinterpret existing laws", "ban all progress", "ignore the technology forever"]'::jsonb,1,'Law adapts to technology.','original'),
('127.677.d.3.A',3,'Using digital information responsibly includes:','["sharing it freely", "altering evidence", "protecting private data and following usage rules", "ignoring policies"]'::jsonb,2,'Responsible use protects privacy and follows rules.','original'),
('127.677.d.3.A',4,'A forensic analyst copies case data to a personal cloud account to work from home. This is:','["required procedure", "best practice", "harmless convenience", "a misuse of sensitive information"]'::jsonb,3,'Case data must stay in approved systems.','original'),
('127.677.d.3.B',3,'Using forensic software responsibly means using it only on:','["systems you are authorized to examine", "neighbors'' networks", "any device you can reach", "strangers'' phones"]'::jsonb,0,'Authorization defines allowed use.','original'),
('127.677.d.3.B',4,'Before using a powerful imaging tool on a device, you should confirm you have:','["a bigger monitor", "legal authorization and a documented purpose", "a faster computer", "a new mouse"]'::jsonb,1,'Authorization and purpose come first.','original'),
('127.677.d.3.C',3,'Which source is most reliable for learning how a forensic tool works?','["a random video comment", "an unsigned chain message", "the vendor''s official documentation or a peer-reviewed study", "an anonymous forum rumor"]'::jsonb,2,'Official and reviewed sources are dependable.','original'),
('127.677.d.3.C',4,'To judge whether an online source is reliable, check its:','["page loading animation", "background color", "number of ads", "author credentials, evidence and date"]'::jsonb,3,'Credibility depends on expertise and evidence.','original'),
('127.677.d.3.D',3,'Informed consent means a person agrees after being told:','["what will be examined and how it will be used", "only the time of day", "nothing at all", "a made-up reason"]'::jsonb,0,'Consent requires understanding.','original'),
('127.677.d.3.D',4,'An employer wants to examine an employee''s personal phone. Which step is most appropriate?','["clone it secretly", "get the employee''s informed consent or a legal order", "take it while they are away", "guess the passcode"]'::jsonb,1,'Consent or legal authority is required.','original'),
('127.677.d.4.A',3,'Which is a common source of data in a digital forensic investigation?','["lunch menus", "parking permits", "hard drives and mobile phones", "wall posters"]'::jsonb,2,'Storage devices hold digital evidence.','original'),
('127.677.d.4.A',4,'Data stored on a suspect''s online account would be collected from a:','["desk drawer only", "copy machine", "paper shredder", "cloud service provider"]'::jsonb,3,'Online data lives with the provider.','original'),
('127.677.d.4.B',3,'After analyzing collected data, an investigator should write a report that is:','["clear, accurate and based on evidence", "vague and opinion-based", "full of guesses", "written to please the suspect"]'::jsonb,0,'Reports must be factual.','original'),
('127.677.d.4.B',4,'A good forensic report separates:','["dates from times", "facts found from the investigator''s interpretations", "files from folders", "people from places"]'::jsonb,1,'Readers must see what is fact and what is opinion.','original'),
('127.677.d.4.C',3,'Which practice helps keep collected evidence from being altered?','["renaming every file", "opening files and editing them", "using a write blocker when copying a drive", "deleting temporary files"]'::jsonb,2,'Write blockers prevent changes.','original'),
('127.677.d.4.C',4,'Encrypting stored evidence mainly protects its:','["brand", "weight", "color", "confidentiality"]'::jsonb,3,'Encryption keeps data private.','original'),
('127.677.d.4.D',3,'Metadata is best described as:','["data about a file, such as its author and creation date", "a printer driver", "the file''s visible text only", "a type of virus"]'::jsonb,0,'Metadata describes other data.','original'),
('127.677.d.4.D',4,'A photo''s metadata could reveal:','["the next photo", "the date taken and the camera model", "the photographer''s bank balance", "the viewer''s password"]'::jsonb,1,'EXIF data stores capture details.','original'),
('127.677.d.4.E',3,'Combining a phone''s call log with network records is useful because it:','["replaces all evidence", "makes data unreadable", "can confirm events by comparing independent sources", "hides contradictions"]'::jsonb,2,'Corroboration strengthens findings.','original'),
('127.677.d.4.E',4,'Correlating logs from a server, a router and a laptop helps an investigator:','["avoid documentation", "delete duplicates", "lose context", "build a more complete timeline"]'::jsonb,3,'Multiple sources fill in gaps.','original'),
('127.677.d.5.A',3,'When comparing two forensic software applications, an investigator should consider:','["supported file systems, accuracy and reporting features", "the splash screen music", "the theme color", "the logo size"]'::jsonb,0,'Capability matters more than looks.','original'),
('127.677.d.5.A',4,'A forensic application that can read many file system types is more useful because it:','["has a longer name", "can examine more kinds of devices", "uses less paper", "looks nicer"]'::jsonb,1,'Broad support widens coverage.','original'),
('127.677.d.5.B',3,'Which application type would most likely hold evidence of a communication between two people?','["a clock app", "a screen magnifier", "an email client", "a calculator"]'::jsonb,2,'Email stores messages.','original'),
('127.677.d.5.B',4,'Peer-to-peer file sharing applications are of interest to investigators because they may be used to:','["adjust screen brightness", "print documents", "check spelling", "transfer illegal or stolen files"]'::jsonb,3,'File sharing can move illicit material.','original'),
('127.677.d.5.C',3,'A file ending in .jpeg is typically a(n):','["image", "audio recording", "spreadsheet", "program"]'::jsonb,0,'JPEG is an image format.','original'),
('127.677.d.5.C',4,'Why do investigators examine unknown .exe files carefully?','["they are always images", "they can run code and may be malicious", "they only hold audio", "they can never change a system"]'::jsonb,1,'Executables run programs.','original'),
('127.677.d.5.D',3,'An application log can show an investigator:','["the software''s price", "the user''s favorite food", "actions the program recorded, with times and users", "the brand of the monitor"]'::jsonb,2,'Logs record activity.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_83_v1'
from (values
('127.677.d.5.D',4,'Database logs can help show whether someone:','["updated a font", "adjusted screen volume", "changed the desktop theme", "queried or changed sensitive records"]'::jsonb,3,'Database logs track data access.','original'),
('127.677.d.5.E',3,'A tool that creates an exact bit-for-bit copy of a drive is a:','["disk imaging tool", "photo editor", "word processor", "media player"]'::jsonb,0,'Imaging duplicates the entire drive.','original'),
('127.677.d.5.E',4,'Why do investigators work from a forensic image rather than the original drive?','["to use more storage", "to avoid changing the original evidence", "to hide the original", "to make the case longer"]'::jsonb,1,'The original must stay untouched.','original'),
('127.677.d.5.F',3,'Choosing a forensic tool based on whether it fits the task and works reliably shows attention to:','["brand loyalty only", "download wait time", "appropriateness and effectiveness", "package color"]'::jsonb,2,'Tools must fit the job and work well.','original'),
('127.677.d.5.F',4,'Two tools both recover deleted files, but one finishes in half the time. Which criterion favors it?','["humor", "decoration", "secrecy", "efficiency"]'::jsonb,3,'Efficiency measures time and resources.','original'),
('127.677.d.5.G',3,'A program''s configuration file mainly stores:','["settings that control how the application behaves", "the monitor resolution only", "the computer''s serial number", "the user''s photos"]'::jsonb,0,'Config files hold settings.','original'),
('127.677.d.5.G',4,'Examining an application''s support files and data folders may reveal:','["only the company logo", "user activity and stored information", "only the app''s icon", "nothing about the user"]'::jsonb,1,'Apps leave traces in their folders.','original'),
('127.677.d.5.H',3,'Incident response as a service lets an organization:','["remove all staff", "avoid ever having incidents", "hire outside experts to handle incidents on demand", "skip investigations"]'::jsonb,2,'Providers supply response help as needed.','original'),
('127.677.d.5.H',4,'A benefit of using an ''as a service'' incident response provider is access to:','["free hardware forever", "legal immunity", "guaranteed zero attacks", "specialized expertise without hiring a full team"]'::jsonb,3,'Outside experts add skills quickly.','original'),
('127.677.d.6.A',3,'During a forensic exam, Windows, macOS and Linux are each a different type of:','["operating systems", "file formats", "web browsers", "network protocols"]'::jsonb,0,'These are operating systems.','original'),
('127.677.d.6.A',4,'An investigator should know several operating systems because evidence is stored differently on:','["paper media", "each operating system", "public bulletin boards", "only one device type"]'::jsonb,1,'Each OS keeps data in its own way.','original'),
('127.677.d.6.B',3,'A file''s creation time tells an investigator:','["who last printed it", "the file owner''s age", "when the file was first created on that system", "how large the monitor was"]'::jsonb,2,'Creation time marks when the file appeared.','original'),
('127.677.d.6.B',4,'A file''s last-accessed time can help show:','["when it was purchased", "where it was manufactured", "how fast the drive spins", "when someone last opened or read the file"]'::jsonb,3,'Access times record viewing activity.','original'),
('127.677.d.6.C',3,'Operating system logs are useful in an investigation because they record:','["logins, errors and system events", "only desktop wallpapers", "only printed pages", "only typed passwords"]'::jsonb,0,'Logs capture system activity.','original'),
('127.677.d.6.C',4,'Windows Event Viewer is used to review:','["email contacts", "system, security and application event logs", "photo albums", "spreadsheet formulas"]'::jsonb,1,'Event Viewer displays Windows logs.','original'),
('127.677.d.6.D',3,'NTFS, ext4 and APFS are examples of:','["programming languages", "network devices", "file systems", "encryption keys"]'::jsonb,2,'File systems organize stored data.','original'),
('127.677.d.6.D',4,'Which file system is the default for modern Windows computers?','["APFS", "HFS", "ext4", "NTFS"]'::jsonb,3,'Windows uses NTFS by default.','original'),
('127.677.d.6.E',3,'Which is an example of secondary storage?','["a solid-state drive", "a register", "RAM", "CPU cache"]'::jsonb,0,'SSDs keep data long term.','original'),
('127.677.d.6.E',4,'Primary storage such as RAM is used mainly to hold:','["long-term archives", "data and programs currently in use", "old photos", "backup tapes"]'::jsonb,1,'RAM holds active work.','original'),
('127.677.d.6.F',3,'Volatile memory such as RAM:','["is always encrypted", "keeps data forever", "loses its contents when power is removed", "can only be read"]'::jsonb,2,'Volatile means temporary.','original'),
('127.677.d.6.F',4,'Why do investigators capture RAM before powering off a running suspect computer?','["it prevents any logs", "it speeds up shutdown", "RAM is permanent", "volatile data like running processes would be lost"]'::jsonb,3,'Shutting down erases memory contents.','original'),
('127.677.d.7.A',3,'A subnet is:','["a smaller segment of a larger network", "a file extension", "an encryption key", "a type of keyboard"]'::jsonb,0,'Subnets divide networks.','original'),
('127.677.d.7.A',4,'Which IPv4 address is a private address?','["151.101.1.69", "192.168.0.15", "8.8.8.8", "93.184.216.34"]'::jsonb,1,'192.168.x.x is a private range.','original'),
('127.677.d.7.B',3,'How many layers does the OSI model have?','["9", "4", "7", "5"]'::jsonb,2,'The OSI model has seven layers.','original'),
('127.677.d.7.B',4,'In the OSI model, the layer responsible for routing packets between networks is the:','["session layer", "presentation layer", "physical layer", "network layer"]'::jsonb,3,'Layer 3 handles routing.','original'),
('127.677.d.7.C',3,'Which protocol in the TCP/IP suite provides reliable, ordered delivery of data?','["TCP", "ICMP", "UDP", "ARP"]'::jsonb,0,'TCP guarantees ordered delivery.','original'),
('127.677.d.7.C',4,'Which TCP/IP layer handles protocols such as HTTP and DNS?','["internet layer", "application layer", "link layer", "transport layer"]'::jsonb,1,'HTTP and DNS are application protocols.','original'),
('127.677.d.7.D',3,'Wireshark helps investigators by letting them:','["design logos", "compile spreadsheets", "capture and inspect network packets", "edit photographs"]'::jsonb,2,'Wireshark is a packet analyzer.','original'),
('127.677.d.7.D',4,'A saved capture of network traffic is often stored in a:','["slide deck", "audio playlist", "font file", "packet capture (pcap) file"]'::jsonb,3,'Captures are saved as pcap files.','original'),
('127.677.d.7.E',3,'A large number of connection attempts to many ports from one address is typical of:','["port scanning", "video streaming", "file printing", "normal browsing"]'::jsonb,0,'Scanners probe many ports.','original'),
('127.677.d.7.E',4,'Unusual large outbound transfers at 3 a.m. to an unknown address may indicate:','["a software update screen", "data exfiltration", "a power saving mode", "routine email"]'::jsonb,1,'Large unexpected uploads suggest stolen data.','original'),
('127.677.d.8.A',3,'Under the principle of least privilege, an intern should be given:','["every password", "full administrator rights", "only the permissions needed for assigned tasks", "no access to anything ever"]'::jsonb,2,'Minimal access is the rule.','original'),
('127.677.d.8.A',4,'Applying least privilege reduces risk mainly because a compromised account can:','["see all files", "do more damage", "bypass logs", "do less damage"]'::jsonb,3,'Limited rights limit the harm.','original'),
('127.677.d.8.B',3,'Granting an employee broader permissions than needed can lead to:','["accidental or intentional misuse of data", "better backups automatically", "lower risk", "faster hardware"]'::jsonb,0,'Excess access raises risk.','original'),
('127.677.d.8.B',4,'Why should permissions be reviewed regularly?','["permissions expire by themselves in all systems", "roles change and old access may no longer be needed", "access should never change", "reviews slow all systems"]'::jsonb,1,'Access should match current roles.','original'),
('127.677.d.8.C',3,'A key card or hardware token is something a user:','["knows", "is", "has", "guesses"]'::jsonb,2,'Tokens are possession factors.','original'),
('127.677.d.8.C',4,'Which is an example of a biometric access component?','["a key card", "a password", "a PIN", "a fingerprint or facial scan"]'::jsonb,3,'Biometrics use body traits.','original'),
('127.677.d.8.D',3,'An access log helps identify suspicious activity by recording:','["who accessed a resource and when", "the temperature", "the weather", "the cafeteria menu"]'::jsonb,0,'Access logs track users and times.','original'),
('127.677.d.8.D',4,'A badge used at a server room door at 2 a.m. by an employee on vacation would appear in the access log as:','["a software update", "a possible sign of misuse", "normal activity", "a system backup"]'::jsonb,1,'It does not fit expected behavior.','original'),
('127.677.d.8.E',3,'When a vendor is given network access, the organization''s risk may increase because the vendor''s:','["systems are always patched", "employees are always trusted", "security weaknesses can become the organization''s weaknesses", "logs are always shared"]'::jsonb,2,'Third-party weaknesses extend your exposure.','original'),
('127.677.d.8.E',4,'A good control before giving a third party access is:','["a verbal hello", "no review", "an unlimited password", "a written agreement defining permitted data use"]'::jsonb,3,'Agreements set clear limits.','original'),
('127.677.d.8.F',3,'Accepting an end user license agreement without reading it can mean agreeing to:','["data collection or usage limits you did not notice", "a refund of all fees", "a guarantee of privacy", "unlimited free upgrades"]'::jsonb,0,'Fine print can include data terms.','original'),
('127.677.d.8.F',4,'An investigator reviewing an app''s terms of service might look for clauses about:','["icon sizes", "data retention and sharing with others", "button shapes", "screen colors"]'::jsonb,1,'Terms reveal how data is kept and shared.','original'),
('127.677.d.8.G',3,'In discretionary access control (DAC), who decides who can access a resource?','["a central policy only", "the network cable", "the resource owner", "random chance"]'::jsonb,2,'Owners grant access in DAC.','original'),
('127.677.d.8.G',4,'In mandatory access control (MAC), access is determined by:','["the owner''s mood", "file size", "each user''s preference", "system-enforced security labels and policies"]'::jsonb,3,'MAC enforces central rules.','original'),
('127.677.d.9.A',3,'Which is the correct order of incident response phases?','["preparation, detection and analysis, containment/eradication/recovery, post-incident activity", "recovery, preparation, detection, lessons", "post-incident, containment, detection, preparation", "detection, post-incident, preparation, containment"]'::jsonb,0,'The cycle begins with preparation and ends with review.','original'),
('127.677.d.9.A',4,'The first phase of the incident response cycle is:','["eradication", "preparation", "lessons learned", "recovery"]'::jsonb,1,'You prepare before incidents occur.','original'),
('127.677.d.9.B',3,'Which action is part of incident response preparation?','["deleting backups", "disabling alarms", "creating a response team and contact list", "waiting for an attack"]'::jsonb,2,'Teams and contacts must exist beforehand.','original'),
('127.677.d.9.B',4,'Practicing a response with a tabletop exercise is part of:','["recovery", "containment", "eradication", "preparation"]'::jsonb,3,'Exercises build readiness.','original'),
('127.677.d.9.C',3,'During detection and analysis, responders:','["confirm whether an incident occurred and determine its scope", "buy new software", "restore from backups", "write the final report"]'::jsonb,0,'They verify and size the incident.','original'),
('127.677.d.9.C',4,'An intrusion detection alert is examined to decide whether it is a:','["backup copy", "true incident or a false positive", "printer error", "new wallpaper"]'::jsonb,1,'Analysts validate alerts.','original'),
('127.677.d.9.D',3,'Disconnecting an infected computer from the network is an example of:','["recovery", "reporting", "containment", "preparation"]'::jsonb,2,'Isolation limits the spread.','original'),
('127.677.d.9.D',4,'Removing malware and closing the vulnerability it used is called:','["detection", "preparation", "containment", "eradication"]'::jsonb,3,'Eradication removes the cause.','original'),
('127.677.d.9.E',3,'A lessons-learned meeting after an incident aims to:','["identify what worked and what to improve", "delete the evidence", "assign blame", "avoid documentation"]'::jsonb,0,'Reviews improve future response.','original'),
('127.677.d.9.E',4,'Findings from a post-incident review are best used to:','["remove staff roles", "update the response plan and security controls", "be filed and forgotten", "disable logging"]'::jsonb,1,'Improvements close gaps.','original')
