('127.679.d.4.C',4,'A mobile device that shares its cellular data connection with other devices is acting as a:','["DNS server", "mobile hotspot", "print server", "firewall"]'::jsonb,1,'Hotspots share the data connection.','original'),
('127.679.d.4.D',3,'An error message is useful to a technician because it:','["can be ignored", "hides the symptom", "gives clues about the cause of a problem", "always fixes the problem"]'::jsonb,2,'Messages point toward causes.','original'),
('127.679.d.4.D',4,'A computer that shows a fan failure warning and shuts down repeatedly is most likely experiencing:','["a missing font", "a wrong wallpaper", "an email problem", "overheating"]'::jsonb,3,'Failed cooling triggers thermal shutdowns.','original'),
